-- Logótipos dos documentos da Financiada: o da DGERT (Configurações › Entidade) e o de cada programa (Edição de
-- cursos › Programas). Vão no rodapé de todos os PDF de uma turma financiada, ao lado do da União Europeia
-- (documentosFin.ts). Chave «dgert» ou «programa:<id do catálogo>».
CREATE TABLE IF NOT EXISTS logos_documentos (
  chave text PRIMARY KEY,
  nome text NOT NULL DEFAULT '',
  mime text NOT NULL,
  bytes bytea NOT NULL,
  hash text NOT NULL,
  updated_at timestamptz NOT NULL DEFAULT now()
);

-- O PESSOAS 2030 fica com os logótipos que o rodapé fixo já tinha (PESSOAS 2030 e Portugal 2030).
INSERT INTO logos_documentos (chave, nome, mime, bytes, hash)
SELECT 'programa:' || id, 'pessoas-2030.png', 'image/png', decode('', 'hex'), 'c580321c1bb435a3fc2fe783c725f3d3650dc0daed9c4a2d08f051bf35c9fa64'
  FROM catalog_items
 WHERE kind = 'programas' AND regime = 'fin' AND payload->>'nome' = 'PESSOAS 2030'
ON CONFLICT (chave) DO NOTHING;
